// Images are generated by the build only when a page points to them, so each
// page that shows Baserow content lists the /media files it uses.
export function prerenderMedia(data: unknown) {
  if (!import.meta.server) return
  const routes = JSON.stringify(data ?? null).match(/\/media\/[\w.-]+/g)
  if (routes) prerenderRoutes([...new Set(routes)])
}
